 setText('combined-phase-status',phaseStatus+' · analysis center '+fmt(layer.phaseAnalysisTimeSeconds===null?NaN:layer.phaseAnalysisTimeSeconds*1e9,'ns',4)+' · causal delay '+fmt(layer.phaseGroupDelaySeconds===null?NaN:layer.phaseGroupDelaySeconds*1e9,'ns',4)+' · upstream total-field probe includes reflections');
